import { type KeyboardEvent, useState } from 'react';
import { Box, Checkbox, Combobox, Input, InputBase, ScrollArea, useCombobox } from '@mantine/core';
import classes from './TreeSelectCheckbox.module.css';

interface TreeNode {
  value: string;
  label: string;
  children?: TreeNode[];
}

const data: TreeNode[] = [
  {
    value: 'frontend',
    label: 'Frontend',
    children: [
      { value: 'react', label: 'React' },
      { value: 'vue', label: 'Vue' },
      { value: 'angular', label: 'Angular' },
    ],
  },
  {
    value: 'backend',
    label: 'Backend',
    children: [
      { value: 'node', label: 'Node.js' },
      { value: 'python', label: 'Python' },
      {
        value: 'go-ecosystem',
        label: 'Go ecosystem',
        children: [
          { value: 'go', label: 'Go' },
          { value: 'gin', label: 'Gin' },
        ],
      },
    ],
  },
  { value: 'devops', label: 'DevOps' },
];

function ChevronIcon({ size = 16 }: { size?: number }) {
  return (
    <svg width={size} height={size} viewBox="0 0 15 15" fill="none" style={{ display: 'block' }}>
      <path
        d="M3.13523 6.15803C3.3241 5.95657 3.64052 5.94637 3.84197 6.13523L7.5 9.56464L11.158 6.13523C11.3595 5.94637 11.6759 5.95657 11.8648 6.15803C12.0536 6.35949 12.0434 6.67591 11.842 6.86477L7.84197 10.6148C7.64964 10.7951 7.35036 10.7951 7.15803 10.6148L3.15803 6.86477C2.95657 6.67591 2.94637 6.35949 3.13523 6.15803Z"
        fill="currentColor"
        fillRule="evenodd"
        clipRule="evenodd"
      />
    </svg>
  );
}

interface FlatNode {
  node: TreeNode;
  level: number;
  parent: string | null;
  hasChildren: boolean;
  expanded: boolean;
  isLastChild: boolean;
  lineGuides: boolean[];
}

function flattenTree(
  nodes: TreeNode[],
  expanded: Record<string, boolean>,
  level: number = 1,
  parentGuides: boolean[] = [],
  parent: string | null = null
): FlatNode[] {
  const result: FlatNode[] = [];
  nodes.forEach((node, index) => {
    const isLast = index === nodes.length - 1;
    const hasChildren = !!node.children?.length;
    const isExpanded = !!expanded[node.value];
    const childGuides = level >= 2 ? [...parentGuides, !isLast] : [];

    result.push({
      node,
      level,
      parent,
      hasChildren,
      expanded: isExpanded,
      isLastChild: isLast,
      lineGuides: level >= 2 ? parentGuides : [],
    });

    if (hasChildren && isExpanded) {
      result.push(...flattenTree(node.children!, expanded, level + 1, childGuides, node.value));
    }
  });
  return result;
}

function findLabel(nodes: TreeNode[], value: string): string | null {
  for (const node of nodes) {
    if (node.value === value) {
      return node.label;
    }
    if (node.children) {
      const found = findLabel(node.children, value);
      if (found) {
        return found;
      }
    }
  }
  return null;
}

function TreeOption({
  flatNode,
  selected,
  onToggleExpand,
}: {
  flatNode: FlatNode;
  selected: boolean;
  onToggleExpand: (value: string) => void;
}) {
  const { node, level, hasChildren, expanded, isLastChild, lineGuides } = flatNode;

  return (
    <Combobox.Option
      value={node.value}
      active={selected}
      className={classes.option}
      mod={{ nested: level > 1, leaf: !hasChildren }}
      style={{ '--level': level }}
    >
      {level > 1 && (
        <>
          {lineGuides.map(
            (show, index) =>
              show && (
                <Box
                  key={index}
                  component="span"
                  className={classes.guide}
                  style={{ '--guide-index': index }}
                />
              )
          )}
          <span className={classes.connector} data-last={isLastChild || undefined} />
          <span className={classes.elbow} />
        </>
      )}
      {hasChildren && (
        <span
          aria-hidden
          className={classes.chevron}
          data-expanded={expanded || undefined}
          onClick={(event) => {
            event.stopPropagation();
            event.preventDefault();
            onToggleExpand(node.value);
          }}
          onMouseDown={(event) => event.preventDefault()}
        >
          <ChevronIcon size={16} />
        </span>
      )}
      <Checkbox.Indicator checked={selected} size="18px" />
      <span className={classes.label}>{node.label}</span>
    </Combobox.Option>
  );
}

export function TreeSelectCheckbox() {
  const store = useCombobox({
    onDropdownClose: () => store.resetSelectedOption(),
  });

  const [value, setValue] = useState<string[]>([]);
  const [expanded, setExpanded] = useState<Record<string, boolean>>({});

  const toggleExpand = (nodeValue: string) => {
    setExpanded((prev) => ({ ...prev, [nodeValue]: !prev[nodeValue] }));
  };

  const flatNodes = flattenTree(data, expanded);

  const handleKeyDown = (event: KeyboardEvent) => {
    if (!store.dropdownOpened) {
      return;
    }

    const index = store.getSelectedOptionIndex();
    if (index < 0 || index >= flatNodes.length) {
      return;
    }

    const current = flatNodes[index];

    if (event.key === 'ArrowRight' && current.hasChildren && !current.expanded) {
      event.preventDefault();
      toggleExpand(current.node.value);
    }

    if (event.key === 'ArrowLeft') {
      if (current.hasChildren && current.expanded) {
        event.preventDefault();
        toggleExpand(current.node.value);
      } else if (current.parent) {
        event.preventDefault();
        const parentIndex = flatNodes.findIndex((n) => n.node.value === current.parent);
        if (parentIndex >= 0) {
          store.selectOption(parentIndex);
        }
      }
    }
  };

  const handleOptionSubmit = (val: string) => {
    setValue((prev) => (prev.includes(val) ? prev.filter((v) => v !== val) : [...prev, val]));
  };

  return (
    <Combobox store={store} withinPortal={false} onOptionSubmit={handleOptionSubmit}>
      <Combobox.Target targetType="button">
        <InputBase
          component="button"
          type="button"
          pointer
          rightSection={<Combobox.Chevron />}
          onClick={() => store.toggleDropdown()}
          onKeyDown={handleKeyDown}
          onBlur={() => store.closeDropdown()}
          rightSectionPointerEvents="none"
          aria-label="Pick technologies"
        >
          {value.length > 0 ? (
            <span className={classes.value}>
              {value.map((val) => findLabel(data, val) ?? val).join(', ')}
            </span>
          ) : (
            <Input.Placeholder>Pick technologies</Input.Placeholder>
          )}
        </InputBase>
      </Combobox.Target>

      <Combobox.Dropdown>
        <ScrollArea.Autosize mah={250} type="scroll" viewportProps={{ tabIndex: -1 }}>
          <Combobox.Options aria-multiselectable>
            {flatNodes.map((flatNode) => (
              <TreeOption
                key={flatNode.node.value}
                flatNode={flatNode}
                selected={value.includes(flatNode.node.value)}
                onToggleExpand={toggleExpand}
              />
            ))}
          </Combobox.Options>
        </ScrollArea.Autosize>
      </Combobox.Dropdown>
    </Combobox>
  );
}

.option {
  --tree-line-gap: 0rem;
  --tree-leaf-gap: 0rem;

  display: flex;
  align-items: center;
  gap: rem(6px);
  position: relative;
  padding-inline-start: calc(
    rem(8px) + (var(--level) - 1) * rem(20px) + var(--tree-line-gap) + var(--tree-leaf-gap)
  );

  &:where([data-nested]) {
    --tree-line-gap: rem(5px);
  }

  &:where([data-leaf]) {
    --tree-leaf-gap: rem(6px);
  }
}

.guide,
.connector,
.elbow {
  position: absolute;
  pointer-events: none;
}

.guide,
.connector {
  top: 0;
  bottom: 0;
  width: 0;
  border-inline-start: 1px solid var(--mantine-color-default-border);
}

.guide {
  inset-inline-start: calc(rem(8px) + var(--guide-index) * rem(20px) + rem(10px));
}

.connector {
  inset-inline-start: calc(rem(8px) + (var(--level) - 1) * rem(20px) - rem(10px));

  &:where([data-last]) {
    bottom: auto;
    height: 50%;
  }
}

.elbow {
  top: 50%;
  height: 0;
  width: rem(10px);
  border-top: 1px solid var(--mantine-color-default-border);
  inset-inline-start: calc(rem(8px) + (var(--level) - 1) * rem(20px) - rem(10px));
}

.chevron {
  display: flex;
  align-items: center;
  justify-content: center;
  width: rem(20px);
  min-width: rem(20px);
  height: rem(20px);
  border-radius: var(--mantine-radius-sm);
  cursor: pointer;
  color: inherit;
  opacity: 0.6;
  transform: rotate(-90deg);
  transition: transform 150ms ease;

  &:where([data-expanded]) {
    transform: rotate(0deg);
  }
}

.label {
  flex: 1;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.value {
  display: block;
  overflow: hidden;
  text-overflow: ellipsis;
}
